import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { getOwnProfile } from "@/lib/auth";
import { AuthButton } from "@/components/auth-button";
import { Button } from "@/components/ui/button";

export default async function Profile() {
  const result = await getOwnProfile(await headers());
  if (result.status === "signed-out") redirect("/");
  return (
    <main className="mx-auto w-full max-w-2xl space-y-6 p-6 sm:py-16">
      {result.status === "available" ? (
        <>
          <h1 className="text-3xl font-semibold tracking-tight">Your Workspace profile</h1>
          <p className="text-muted-foreground">Current shared information from Google Workspace.</p>
          <dl className="space-y-5 rounded-xl border p-6">
            <div>
              <dt className="font-medium">Name</dt>
              <dd>{result.profile.name?.fullName ?? "Unavailable"}</dd>
            </div>
