const subscribe = () => () => {};

export function AuthButton({
  action = "sign-in",
}: {
  action?: "sign-in" | "sign-out" | "reconnect";
}) {
  const [pending, setPending] = useState(false);
  const ready = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
  const [error, setError] = useState(false);
  async function run() {
